
str1 = ""

str2 = ""

input_text = "Orice text clar poate obtinut dintr-un text criptat cu OTP dar cu alta cheie..."


def xor_two_strings(string1, string2):
    res = ""
    for idx in range(0, len(string1)):
        dig1 = ord(string1[idx]) - ord('0')
        dig2 = ord(string2[idx]) - ord('0')
        dig = dig1 ^ dig2
        new_dig = chr(dig + ord('0'))
        res += new_dig
    return res

def convert_binary_to_text(binary_string):
    ans = ""
    size = len(binary_string)
    # print(size)
    for i in range(0, size // 8):
        num = 0
        pw = 1
        for j in range(7, -1, -1):
            idx = i * 8 + j
            num += pw * (ord(binary_string[idx]) - ord('0'))
            pw <<= 1
        ans += chr(num)
    return ans


def convert_text_to_binary(text):
    binary_string = ""
    print(len(text) * 8)
    for let in text:
        num = ord(let)
        temp_str = ""
        for i in range(0, 8):
            if num & (1 << i):
                temp_str = "1" + temp_str
            else:
                temp_str = "0" + temp_str
        binary_string += temp_str
    return binary_string

